// Test-only GPG helpers.
//
// Every command receives an explicit GNUPGHOME, so a test can never read, use or
// modify the operator's real keyring. The passphrase is generated by the caller,
// supplied to key generation over stdin, and sent to gpg-agent over stdin. It is
// never written to disk or placed in argv.
import { spawnSync } from 'node:child_process';
import { mkdir, writeFile } from 'node:fs/promises';
import path from 'node:path';

/** MSYS gpg/tar read POSIX paths; Node and Windows gpg accept the drive form. */
export function gpgPath(value) {
  if (process.platform !== 'win32') return value;
  return path
    .resolve(value)
    .replaceAll('\\', '/')
    .replace(/^([A-Za-z]):/, (_, drive) => `/${drive.toLowerCase()}`);
}

export function gpgEnv(home, base = process.env) {
  const env = { ...base };
  if (home) env.GNUPGHOME = gpgPath(home);
  return env;
}

export function runGpg(command, args, { home, input, timeout = 120_000 } = {}) {
  const result = spawnSync(command, args, {
    env: gpgEnv(home),
    encoding: 'utf8',
    input,
    timeout,
  });
  if (result.error) throw result.error;
  return {
    code: result.status,
    signal: result.signal,
    stdout: String(result.stdout || ''),
    stderr: String(result.stderr || ''),
  };
}

export function must(result, label) {
  if (result.code !== 0) {
    throw new Error(
      `${label} failed with exit ${result.code ?? result.signal}: ${result.stderr.trim().slice(0, 600)}`,
    );
  }
  return result;
}

export function firstField(output, record) {
  return output
    .split(/\r?\n/)
    .find((line) => line.startsWith(`${record}:`))
    ?.split(':')[9];
}

/**
 * Generate a protected encryption key in the caller's temporary GNUPGHOME.
 * `--passphrase-fd 0` is the point: the passphrase arrives over stdin, never in
 * argv or a file the test reads back.
 */
export async function createProtectedTestKey({ home, passphrase, uid = 'Inventory Backup Unit Test <backup-unit@example.invalid>' }) {
  await mkdir(home, { recursive: true });
  must(
    runGpg(
      'gpg',
      [
        '--batch',
        '--pinentry-mode',
        'loopback',
        '--passphrase-fd',
        '0',
        '--quick-generate-key',
        uid,
        'rsa2048',
        'encr',
        '0',
      ],
      { home, input: `${passphrase}\n` },
    ),
    'protected test key generation',
  );

  const keys = must(
    runGpg('gpg', ['--batch', '--with-colons', '--with-keygrip', '--list-secret-keys'], {
      home,
    }),
    'protected test key listing',
  ).stdout;
  return {
    fingerprint: firstField(keys, 'fpr') || '',
    keygrip: firstField(keys, 'grp') || '',
  };
}

export function clearAgentCache(home) {
  // `gpgconf --kill` is the strongest cache clear available: it stops the agent
  // and discards every cached passphrase. Starting a new agent later therefore
  // proves the next decrypt is using only the preset supplied by the test.
  return must(runGpg('gpgconf', ['--kill', 'gpg-agent'], { home }), 'gpg-agent cache clear');
}

export async function allowPresetPassphrase(home) {
  await writeFile(path.join(home, 'gpg-agent.conf'), 'allow-preset-passphrase\n');
}

export function startAgent(home) {
  return must(runGpg('gpg-connect-agent', ['/bye'], { home }), 'gpg-agent start');
}

/** Preset the passphrase over stdin, never as an argv value. */
export function presetPassphrase({ home, keygrip, passphrase }) {
  const hex = Buffer.from(passphrase, 'utf8').toString('hex');
  return must(
    runGpg('gpg-connect-agent', [], {
      home,
      input: `PRESET_PASSPHRASE ${keygrip} -1 ${hex}\n/bye\n`,
    }),
    'gpg-agent passphrase preset',
  );
}
